/// <summary>
/// PricingAttribute of table <c>METCustTable</c> field CustOperGroupId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, METCustOperGroupId))]
internal class METGUPPricingAttributeCustTableCustOprGrp extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

